?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tình huống từ cộng đồng · Siêu Nhí AI</title><link rel="stylesheet" href="assets/css/fonts.css?v=1"><link rel="stylesheet" href="assets/css/style.css?v=12"><link rel="stylesheet" href="assets/css/shared-pages.css?v=28"><link rel="stylesheet" href="assets/css/kid-components.css?v=1"></head><body><main class="wrap community-page"><div class="page-head"><span class="eyebrow-pill"><span class="dot"></span> Tình huống đã kiểm duyệt</span><h1>Góc đường phố an toàn</h1><p>Những quan sát thực tế được phụ huynh và giáo viên gửi, AI và quản trị viên kiểm tra trước khi chia sẻ.</p><a class="btn btn-primary-sm" href="community.php">📤 Gửi tình huống</a></div><div class="community-feed"><?php if (!$reports): ?><div class="card empty-state">Chưa có tình huống được duyệt. Hãy là người đầu tiên chia sẻ.</div><?php endif; ?><?php foreach ($reports as $report): ?><article class="card feed-card"><?php if (!empty($report['image_path'])): ?><img src="community-image.php?file=<?= e(basename($report['image_path'])) ?>" alt="<?= e($report['title']) ?>" loading="lazy"><?php endif; ?><div><small><?= e($report['province'] ?: 'Việt Nam') ?></small><h3><?= e($report['title']) ?></h3><p><?= nl2br(e($report['description'])) ?></p></div></article><?php endforeach; ?></div></main><script src="assets/js/main.js?v=8"></script></body></html>
